import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"传送系统","description":"","frontmatter":{},"headers":[],"relativePath":"teleport.md","filePath":"teleport.md"}'),r={name:"teleport.md"};function l(h,t,i,c,n,s){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="传送系统" tabindex="-1">传送系统 <a class="header-anchor" href="#传送系统" aria-label="Permalink to &quot;传送系统&quot;">​</a></h1><p>传送系统是服务器最常用的功能，帮助你快速到达目的地。本页涵盖：<a href="#回到主城">回到主城</a> / <a href="#家-home">家（Home）</a> / <a href="#传送点-warp">传送点（Warp）</a> / <a href="#玩家传送-tpa">玩家传送（TPA）</a> / <a href="#返回-back">返回（Back）</a> / <a href="#主城弹射-pej">主城弹射（/pej）</a>。</p><h2 id="回到主城" tabindex="-1">回到主城 <a class="header-anchor" href="#回到主城" aria-label="Permalink to &quot;回到主城&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/spawn</code></td><td>传送回主城</td></tr></tbody></table><ul><li>在任何世界死亡后，都会在主城重生。</li><li>主城是安全区，禁止 PvP，可以放心挂机。</li></ul><h2 id="家-home" tabindex="-1">家（Home） <a class="header-anchor" href="#家-home" aria-label="Permalink to &quot;家（Home）&quot;">​</a></h2><p>家可以记录你指定的位置，随时一键返回。</p><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/sethome [名字]</code></td><td>把当前位置设为家</td></tr><tr><td><code>/home [名字]</code></td><td>传送到家</td></tr><tr><td><code>/delhome [名字]</code></td><td>删除家</td></tr><tr><td><code>/homes</code></td><td>查看所有家</td></tr><tr><td><code>/phome [名字]</code></td><td>传送到某玩家的公开家</td></tr></tbody></table><p><strong>家数量规则：</strong></p><ul><li>每个玩家最多 <strong>16 个家</strong>。</li><li>前 <strong>8 个免费</strong>，第 9 个起每个需要支付 <strong>8 钻石</strong>。</li><li>家名可以自定义，支持中文，最长 16 个字符。</li></ul><p><strong>公开家：</strong></p><ul><li>把家设为公开后，其他玩家可以通过 <code>/phome [名字]</code> 访问。</li><li>将家设为公开需要支付 <strong>16 钻石</strong>。</li><li>公开家最多 <strong>5 个</strong>。</li></ul><h2 id="传送点-warp" tabindex="-1">传送点（Warp） <a class="header-anchor" href="#传送点-warp" aria-label="Permalink to &quot;传送点（Warp）&quot;">​</a></h2><p>服务器或玩家设置的特殊地点，可用 <code>/warp [名字]</code> 前往。输入 <code>/warp</code> 可查看可用的传送点列表。</p><h2 id="玩家传送-tpa" tabindex="-1">玩家传送（TPA） <a class="header-anchor" href="#玩家传送-tpa" aria-label="Permalink to &quot;玩家传送（TPA）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/tpa &lt;玩家&gt;</code></td><td>请求传送到对方身边</td></tr><tr><td><code>/tpahere &lt;玩家&gt;</code></td><td>邀请对方传送到你身边</td></tr><tr><td><code>/tpaccept</code></td><td>接受收到的传送请求</td></tr><tr><td><code>/tpdeny</code></td><td>拒绝传送请求</td></tr><tr><td><code>/tpignore &lt;玩家&gt;</code></td><td>不再接收该玩家的传送请求</td></tr></tbody></table><p><strong>注意：</strong></p><ul><li>传送请求的有效期为 <strong>60 秒</strong>，超时自动失效，需重新发起。</li><li>对方必须在线才能传送。</li></ul><h2 id="返回-back" tabindex="-1">返回（Back） <a class="header-anchor" href="#返回-back" aria-label="Permalink to &quot;返回（Back）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/back</code></td><td>返回上次的位置（例如死亡地点、上次传送前的位置）</td></tr></tbody></table><h2 id="传送提醒" tabindex="-1">传送提醒 <a class="header-anchor" href="#传送提醒" aria-label="Permalink to &quot;传送提醒&quot;">​</a></h2><ul><li>传送需要 <strong>2 秒</strong>准备时间（读条）。</li><li>读条期间<strong>移动或受到伤害</strong>会取消传送，请站定等待。</li></ul><h2 id="主城弹射-pej" tabindex="-1">主城弹射（/pej） <a class="header-anchor" href="#主城弹射-pej" aria-label="Permalink to &quot;主城弹射（/pej）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/pej</code></td><td>在主城使用，将你弹射前往主世界</td></tr></tbody></table><ul><li>输入后等待 <strong>5 秒</strong>倒计时，你将被弹射到主世界上空并安全降落（落地后短时间免疫摔落伤害）。</li><li>该指令仅在<strong>主城</strong>生效。</li><li>使用前请确保周围无障碍物、头顶空旷。</li></ul><h2 id="小提示" tabindex="-1">小提示 <a class="header-anchor" href="#小提示" aria-label="Permalink to &quot;小提示&quot;">​</a></h2><ul><li>出发冒险前记得 <code>/sethome</code> 设置家，随时安全返回。</li><li><code>/rtp</code> 随机传送功能当前<strong>未开放</strong>。</li><li>聊天栏中单击玩家名字所在的世界（形如 <code>[主世界]</code>），效果与 <code>/tpa</code> 相同。</li></ul>',27)])])}const u=e(r,[["render",l]]);export{b as __pageData,u as default};
